149	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe, xe máy và hai chế độ xem)
150	    if (watching || stroll.inMode() || drive.inMode() || bike.inMode()) return;   // xem: không lái; đi dạo / lái xe / xe máy: phím do stroll/index.ts, drive/index.ts, bike/index.ts ghi
151	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
