167	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
168	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
169	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
170	  if (q.get('explore') === 'glider') { explore.start(); return; }
171	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
172	  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
173	  if (q.get('explore') === 'bike') { bike.start(); return; }     // xe máy một mình
174	  if (!q.has('test') || q.has('chooser')) {
175	    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload());   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
176	    document.querySelector('button[data-pick="glider"]')?.addEventListener('click', () => plPreload());   // chọn thẻ Dù lượn: nạp người treo ngay, trong lúc ở sảnh
177	    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
178	    document.querySelector('button[data-pick="bike"]')?.addEventListener('click', () => bike.preload());   // chọn thẻ Xe máy: nạp mô hình xe máy ngay (Task 3)
179	    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); else if (choice === 'bike') bike.start(); },
180	      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else if (choice === 'bike') bike.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
