1	import * as THREE from 'three';
2	import { camera, controls } from '../core/renderer';
3	import { clamp } from '../common/math';
4	import { CONFIG } from '../config';
5	import { t, stops, onChange } from '../i18n';
6	import { narration } from '../audio/narration';
7	import { TOUR_DEFS, type TourDef, type TourStop } from './tourStops';
8	import type { BridgeKey } from './presets';
9	import { cam } from './state';
10	
11	/* ============================ Tour tự động: đường bay + chú thích ============================ */
12	/* loop: false — đường bay mở (Tour 4 cầu): n − 1 đoạn bay + một đoạn "giữ" ở điểm cuối, hết thì trả điều khiển */
13	interface Tour extends TourDef {
14	  loop: boolean; posCurve: THREE.CatmullRomCurve3; tgtCurve: THREE.CatmullRomCurve3; base: number[]; durs: number[]; total: number;
15	}
16	export type TourKey = keyof typeof TOUR_DEFS;
17	export const TOURS = {} as Record<TourKey, Tour>;
18	for (const [k, T] of Object.entries(TOUR_DEFS) as [TourKey, TourDef][]) {
19	  const P = T.stops.map((s) => new THREE.Vector3(...s.pos)), Q = T.stops.map((s) => new THREE.Vector3(...s.target));
20	  const loop = T.loop !== false;
21	  const durs = P.map((p, i) => !loop && i === P.length - 1 ? CONFIG.tourAll.holdMin   // đoạn giữ ở điểm cuối
22	    : clamp(4 + p.distanceTo(P[(i + 1) % P.length]) / 45, 8, T.segMax ?? 16));           // đoạn dài bay lâu hơn để tốc độ đều
23	  TOURS[k] = {
24	    ...T, loop,
25	    posCurve: new THREE.CatmullRomCurve3(P, loop, 'centripetal'),
26	    tgtCurve: new THREE.CatmullRomCurve3(Q, loop, 'centripetal'),
27	    base: durs, durs: [...durs], total: durs.reduce((a, b) => a + b, 0)
28	  };
29	}
30	
31	/* Chú thích (và giọng đọc) chuyển sang điểm kế khi đi qua tỉ lệ này của đoạn bay */
32	const SWITCH = 0.55, PAD = 1.2;
33	
34	/* Có giọng thuyết trình thì kéo dài từng đoạn bay để đọc xong trước khi sang điểm dừng kế.
35	   Điểm dừng k hiện từ lúc 55% đoạn k-1 tới 55% đoạn k; chỉ đoạn k được kéo dài nên các điểm đã đủ chỗ vẫn đủ.
36	   Đường bay mở: điểm 0 hiện ngay từ đầu (không có đoạn trước); điểm cuối hiện tới hết đoạn giữ. */
37	function fitDurations(T: Tour) {
38	  const n = T.stops.length;
39	  T.durs.splice(0, n, ...T.base);
40	  for (let k = 0; k < n; k++) {
41	    const spoken = narration.duration(T.key, k), clip = Math.max(spoken ?? 0, T.stops[k].minSec ?? 0);   // minSec: giữ điểm này ít nhất chừng đó giây dù không có giọng
42	    if (spoken === null && !T.stops[k].minSec) continue;
43	    const prev = (k + n - 1) % n, before = !T.loop && k === 0 ? 0 : (1 - SWITCH) * T.durs[prev];
