86	export function drEnsureNet(): DrNet {
87	  if (!net) {
88	    const n = drMakeNet(drBuildPads(), drBuildSolids());
89	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
