96	/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
97	   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng: drEvacStep coi 0 là hết hạn (trượt trong evac.minTime), khác bỏ trống (không hạn) */
98	function drSwingBudget(c: SwingController): number {
99	  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
100	  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
101	  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
102	  return 0;
103	}
