134	/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như stOnMultiChange của đi dạo) */
135	function drOnMultiChange(): void {
136	  const s = exMulti.session; if (!s) return;
137	  if (watching) {
138	    if (s.phase === 'flying') { drive.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường
139	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostDrive'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện drLostChooser
140	    exWatchRender();
141	  } else if (active()) {
142	    if (s.phase === 'watching') { drive.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
143	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'drLost');   // vẫn lái, người khác đã biến mất
144	  }
