147	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
148	   Dùng cho test (__app.drive) và đặt lại vị trí */
149	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
150	  if (!net) return;
151	  const s = drCreate(net, DR_SOLO_SLOT);
152	  let gy = -Infinity;
153	  for (const p of net.pads) {
154	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
155	    gy = Math.max(gy, p.y(x, z));
156	  }
157	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
158	  state = s;
159	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
160	  drCars.place(selfSlot, s);
161	  drCamPlace(camera, s, camS, net, 0, true);
162	  controls.target.set(s.x, s.y, s.z);
163	}
