165	export const drive = {
166	  active,
167	  inMode,
168	  get watching(): boolean { return watching; },
169	  get state(): DrState | null { return state; },
170	  get net(): DrNet | null { return net; },
171	  get cam(): DrCam { return camS; },
172	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot, màu xe theo slot) */
173	  start(): void {
174	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
175	    drUseBody(DR_CAR_BODY);   // thân va chạm ô tô (chế độ xe máy có thể đã đổi sang thân xe máy trong cùng trang)
176	    const n = drEnsureNet(), s = exMulti.session;
177	    const slot = s && s.kind === 'drive' && s.mySlot >= 0 ? s.mySlot : DR_SOLO_SLOT;
178	    if (s) exMulti.onChange = drOnMultiChange;
179	    selfSlot = slot >= 0 ? slot : DR_SELF;
180	    state = drCreate(n, slot);
181	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
182	    exDrivers.setSelf(selfSlot);   // dựng xe của mình; drCars.group vào cảnh nhờ exDrivers.onCars (multi/index.ts)
183	    drCars.place(selfSlot, state);
184	    driveView.far = CONFIG.drive.tunnelFar;
185	    drKeys.clear(); touch?.reset();
186	    drHudShow(n); drSound.start();
187	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
188	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
189	    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
190	    drCamPlace(camera, state, camS, n, 0, true);
191	    controls.target.set(state.x, state.y, state.z);
192	    document.body.classList.add('explore', 'drive');
193	  },
194	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'car' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng mô tơ;
195	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
196	  startWatching(carry = false): void {
197	    const s = exMulti.session; if (!s) return;
198	    drUseBody(DR_CAR_BODY);
199	    const n = drEnsureNet();
200	    state = null; watching = true; chased = carry;
201	    drKeys.clear(); touch?.reset(); drSound.stop();
202	    exDrivers.setSelf(-1);
203	    driveView.far = CONFIG.drive.tunnelFar;
204	    drHudShow(n);
205	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
206	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
207	    camera.fov = CONFIG.drive.cam.fov; onResize();
208	    document.body.classList.add('explore', 'drive', 'ex-watching');
209	    exMulti.onChange = drOnMultiChange;
210	    exWatchShow(s);
211	  },
212	  update(dt: number): void {
213	    if (watching) { watchStep(dt); return; }
214	    if (!active()) return;
215	    drInputFromKeys(drKeys, _inp);
216	    if (touch) touch.read(_inp);   // gộp, không xóa phím
217	    drSound.horn(drKeys.has('KeyH'));
218	    advance(dt, _inp);
219	  },
220	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho HUD / chụp ảnh của task sau */
221	  afterRender(): void { /* chưa có việc */ },
222	  /* Rời chế độ: trả mọi thứ đã đổi (explore.exit tải lại trang ngay sau), kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'car' */
223	  stop(): void {
224	    if (state === null && !watching) return;
225	    state = null; drKeys.clear(); touch?.reset();
226	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
